/**
 * Replaces the old flat-`summary` Technical Briefing card in its exact hero slot -- same
 * `PulseCard(SYNTHESIS)` position at the top of the Dashboard. Merges what used to be two
 * separate AI cards (Technical Briefing's `synthesis.{headline,detail}` narrative and the new
 * market-wide Daily Digest sections) into one: `headline`/`detail` render exactly like
 * `SynthesisHeroCard` (bold headline, tap-to-expand body), then `sections` render exactly like
 * stock-detail's `DigestCard` (uppercase heading label + body, divider between blocks) --
 * `daily_digest`'s own `headline` field is deliberately not surfaced separately, since this card
 * already has one headline slot (`synthesis.headline`) and a second competing headline would just
 * fight it for the same space.
 *
 * `isEquityOpen` carries over the market-open/closed `SignalPill` badge the old `TechnicalSummaryCard`
 * rendered at the bottom of this same card -- unrelated to the AI content above it (it's live market-
 * hours status, not a synthesis field), so it renders unconditionally regardless of `isUnavailable`.
 *
 * Collapsed state shows the headline plus a 3-line clamp of `detail` (the app-wide default for any
 * AI-synthesis body text -- see `docs/theming-system/card-heading-conventions.md`'s Seventeenth
 * step), matching `SynthesisHeroCard`. This card goes one step further than `SynthesisHeroCard`
 * though: `sections` are gated behind the same expand toggle too (not shown at all until expanded),
 * since several digest sections stacked below an already-3-line-clamped detail would otherwise make
 * the "collapsed" state read as not collapsed at all.
 */
@Composable
fun DailyDigestHeroCard(
    headline: String?,
    detail: String?,
    sections: List<DomainDigestSection>,
    isUnavailable: Boolean,
    isEquityOpen: Boolean,
    modifier: Modifier = Modifier
) {
    var isExpanded by remember { mutableStateOf(false) }
    val pulseColors = LocalPulseColors.current
    val paddingMedium = dimensionResource(id = R.dimen.padding_medium)
    val paddingLarge = dimensionResource(id = R.dimen.padding_large)
    val paddingSmall = dimensionResource(id = R.dimen.padding_small)

    val badgeBgColor =
        if (isEquityOpen) pulseColors.signalBullishPill else MaterialTheme.colorScheme.surfaceVariant
    val badgeTextColor =
        if (isEquityOpen) pulseColors.signalBullishText else MaterialTheme.colorScheme.onSurfaceVariant

    val hasContent = !headline.isNullOrBlank() || sections.isNotEmpty()
    val hasExpandableContent = !detail.isNullOrBlank() || sections.isNotEmpty()

    PulseCard(
        style = PulseCardStyle.SYNTHESIS,
        modifier = modifier.fillMaxWidth(),
        onClick = if (hasExpandableContent) { { isExpanded = !isExpanded } } else null
    ) {
        Column(modifier = Modifier.padding(paddingLarge).animateContentSize()) {
            CardEyebrowLabel(
                text = stringResource(id = R.string.dashboard_daily_digest_header),
                color = pulseColors.accentPrimary,
                iconRes = R.drawable.ic_ai_sparkle_filled
            )

            if (isUnavailable || !hasContent) {
                Spacer(modifier = Modifier.height(paddingMedium))
                Text(
                    text = stringResource(id = R.string.dashboard_daily_digest_unavailable),
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            } else {
                if (!headline.isNullOrBlank()) {
                    Spacer(modifier = Modifier.height(paddingMedium))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = headline.smartTitleCase(),
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                            color = MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier.weight(1f)
                        )
                        if (hasExpandableContent) {
                            Spacer(modifier = Modifier.width(paddingSmall))
                            Icon(
                                painter = painterResource(id = if (isExpanded) R.drawable.ic_arrow_up else R.drawable.ic_arrow_down),
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(paddingLarge)
                            )
                        }
                    }
                }

                if (!detail.isNullOrBlank()) {
                    Spacer(modifier = Modifier.height(paddingMedium))
                    Text(
                        text = detail,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurface,
                        maxLines = if (isExpanded) Int.MAX_VALUE else 3,
                        overflow = TextOverflow.Ellipsis
                    )
                }

                if (isExpanded) {
                    sections.forEach { section ->
                        Spacer(modifier = Modifier.height(paddingLarge))
                        HorizontalDivider(
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                            thickness = dimensionResource(id = R.dimen.border_thin)
                        )
                        Spacer(modifier = Modifier.height(paddingLarge))
                        Text(
                            text = section.heading.orEmpty().uppercase(),
                            style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                            color = pulseColors.accentPrimary
                        )
                        Spacer(modifier = Modifier.height(paddingSmall))
                        Text(
                            text = section.body.orEmpty(),
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(paddingLarge))
            SignalPill(
                text = if (isEquityOpen) stringResource(id = R.string.dashboard_market_open)
                else stringResource(id = R.string.dashboard_market_closed),
                pillColor = badgeBgColor,
                contentColor = badgeTextColor,
                leadingIcon = {
                    Box(
                        modifier = Modifier
                            .size(dimensionResource(id = R.dimen.icon_size_small))
                            .background(color = badgeTextColor, shape = CircleShape)
                    )
                }
            )
        }
    }
}

